package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamTripitakaBank1 {
  private const val T = "ත්‍රිපිටකය හා ධර්ම සංගායනා ඉතිහාසය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("බුදුරජාණන් වහන්සේ පන්සාළිස් වසක් පුරා දේශනා කළ ශ්‍රී සද්ධර්මය සංග්‍රහ කර ඇති ප්‍රධාන පිටක තුන මොනවාද?", "විනය, සූත්‍ර හා අභිධර්ම පිටක", "නිකාය, ජාතක හා වංශ පිටක", "ගද්‍ය, පද්‍ය හා චම්පු පිටක", "ශ්‍රැති, ස්මෘති හා උපනිෂද් පිටක", "ත්‍රිපිටකය යනු විනය, සූත්‍ර සහ අභිධර්ම යන පිටක තුනයි."),
    q("'පිටක' යන පාලි වචනයෙහි සැබෑ අර්ථය කුමක්ද?", "පැස හෙවත් භාජනය (ධර්මය තැන්පත් කළ පැස)", "කඩුව", "මල්මාලාව", "සිංහාසනය", "සද්ධර්මය සුරක්ෂිතව අඩංගු කර ඇති භාජනයක් බඳු බැවින් පිටක නම් වේ."),
    q("ත්‍රිපිටකයේ ප්‍රධාන පිටක තුනෙන් භික්ෂු හා භික්ෂුණී ශාසනයේ විනය නීති අඩංගු වන්නේ කුමන පිටකයේද?", "විනය පිටකයේ", "සූත්‍ර පිටකයේ", "අභිධර්ම පිටකයේ", "ඛුද්දක නිකායේ", "පැවිදි පිරිසගේ ආචාර ධර්ම හා ශාසනික නීති විනය පිටකයේ අඩංගු වේ."),
    q("බුද්ධ ශාසනයේ ආයුෂ පවතින්නේ කුමක් මතදැයි පළමු සංගායනාවේදී මහා කාශ්‍යප හිමියන් ප්‍රකාශ කළේද?", "විනය පවතින තුරු (විනයෝ නාම සාසනස්ස ආයු)", "ධනය පවතින තුරු", "රජවරුන් සිටින තුරු", "විහාර පවතින තුරු", "විනය මූලික කරගෙන පළමු සංගායනාවේදී මුලින්ම විනය පිටකය සංගායනා කෙරිණි."),
    q("විනය පිටකය ප්‍රධාන ග්‍රන්ථ පහකට බෙදී ඇත. ඊට අයත් පළමු ග්‍රන්ථය කුමක්ද?", "පාරාජිකා පාලිය", "පාචිත්තිය පාලිය", "මහාවග්ග පාලිය", "පරිවාර පාලිය", "පාරාජිකා, පාචිත්තිය, මහාවග්ග, චුල්ලවග්ග, පරිවාර යනු විනය පිටකයේ ග්‍රන්ථ පහයි."),
    q("විනය පිටකයේ මහාවග්ග හා චුල්ලවග්ග යන ග්‍රන්ථ දෙක හඳුන්වන්නේ කුමන පොදු නමකින්ද?", "ඛන්ධක පාලිය", "සුත්තවිභංගය", "පරිවාර පාලිය", "අට්ඨකථා", "සංඝ කර්ම හා විනය නීති විස්තර කෙරෙන කොටස ඛන්ධක නම් වේ."),
    q("පාරාජිකා හා පාචිත්තිය යන විනය ග්‍රන්ථ දෙක එක්ව හඳුන්වන්නේ කෙසේද?", "සුත්තවිභංගය (හෙවත් උභතෝවිභංගය)", "ඛන්ධකය", "පරිවාරය", "කථාවත්ථු", "භික්ෂු විභංගය හා භික්ෂුණී විභංගය ලෙස විනය ශික්ෂාපද විස්තර කෙරේ."),
    q("විනය පිටකය පිළිබඳ ප්‍රශ්නෝත්තර ස්වරූපයෙන් සකස් වූ සමාලෝචන ග්‍රන්ථය කුමක්ද?", "පරිවාර පාලිය", "මහාවග්ග පාලිය", "පාරාජිකා පාලිය", "චුල්ලවග්ග පාලිය", "මුළු විනය පිටකයේම සාරාංශය හා නීති පැහැදිලි කිරීම් පරිවාර පාලියේ එයි."),
    q("භික්ෂුවකට පැවිදි භාවය අහිමි වන බරපතළම විනය වැරදි හතර හඳුන්වන්නේ කෙසේද?", "සතර පාරාජිකා", "තෙළෙස් සංඝාදිසේස", "පාචිත්තිය", "දුක්කට", "මෛථුන, අදත්තාදාන, මනුෂ්‍යවිග්‍රහ, උත්තරිමනුස්සධම්ම යනු පාරාජිකා සතරයි."),
    q("භික්ෂූන් වහන්සේලා පොහොය දිනයකදී රැස්වී සජ්ඣායනා කරන විනය ශික්ෂාපද සංග්‍රහය කුමක්ද?", "පාතිමෝක්ෂය", "ධම්මසංගණිය", "පෙටකෝපදේශය", "මිලින්දපඤ්හය", "භික්ෂු පාතිමෝක්ෂයේ ශික්ෂාපද 227 ක් අඩංගු වේ."),
    q("භික්ෂු පාතිමෝක්ෂයට අයත් මුළු ශික්ෂාපද ගණන කීයද?", "227 කි", "311 කි", "150 කි", "500 කි", "උපසම්පදා භික්ෂුවක් විසින් ආරක්ෂා කළ යුතු ශික්ෂාපද 227 කි."),
    q("භික්ෂුණී පාතිමෝක්ෂයේ අඩංගු වන මුළු ශික්ෂාපද සංඛ්‍යාව කීයද?", "311 කි", "227 කි", "400 කි", "108 කි", "භික්ෂුණීන් වහන්සේලා සඳහා පනවා ඇති විනය ශික්ෂාපද ගණන 311 කි."),
    q("බුදුරදුන් සමයේ විවිධ අවස්ථාවලදී පුද්ගලයන් හා සිදුවීම් අරභයා දේශනා කළ ධර්ම කොටස් අයත් පිටකය කුමක්ද?", "සූත්‍ර පිටකය", "විනය පිටකය", "අභිධර්ම පිටකය", "ටීකා පිටකය", "ව්‍යවහාර දේශනා ලෙස සාමාන්‍ය ජනයාට වැටහෙන පරිදි දෙසූ දේශනා සූත්‍ර පිටකයයි."),
    q("සූත්‍ර පිටකය ප්‍රධාන නිකාය කීයකට බෙදා වෙන් කර ඇත්ද?", "පහකට (පංච නිකාය)", "තුනකට", "හතකට", "දෙකකට", "දීඝ, මජ්ඣිම, සංයුත්ත, අංගුත්තර, ඛුද්දක යනු පංච නිකායයි."),
    q("පංච නිකායෙන් දීර්ඝ සූත්‍ර 34 කින් සමන්විත පළමු නිකාය කුමක්ද?", "දීඝ නිකාය", "මජ්ඣිම නිකාය", "සංයුත්ත නිකාය", "අංගුත්තර නිකාය", "සීලක්ඛන්ධ, මහා, පාථික යන වග්ග තුනේ සූත්‍ර 34 ක් දීඝ නිකායේ ඇත."),
    q("මධ්‍යම ප්‍රමාණයේ සූත්‍ර දේශනා 152 ක් ඇතුළත් නිකාය කුමක්ද?", "මජ්ඣිම නිකාය", "දීඝ නිකාය", "අංගුත්තර නිකාය", "ඛුද්දක නිකාය", "මූල, මජ්ඣිම, උපරි පණ්ණාසක වශයෙන් කොටස් තුනකින් යුක්තය."),
    q("විෂය අනුසාරයෙන් කාණ්ඩවලට ගලපා සකස් කර ඇති සංයුත්ත නිකායේ වග්ග ගණන කීයද?", "පහකි", "තුනකි", "හතරකි", "දසයකි", "සගාථ, නිදාන, ඛන්ධ, සළායතන, මහා යන වග්ග 5 න් සමන්විතය."),
    q("අංගුත්තර නිකායේ අඩංගු නිපාත ගණන කීයද?", "එකොළහකි (ඒකක සිට ඒකාදසක දක්වා)", "පහකි", "හතකි", "විස්සකි", "කරුණු සංඛ්‍යාව අනුව සූත්‍ර පෙළගස්වා ඇති නිකාය අංගුත්තර නිකායයි."),
    q("සූත්‍ර පිටකයේ වැඩිම ග්‍රන්ථ සංඛ්‍යාවක් (ග්‍රන්ථ 15 ක්) ඇතුළත් වන නිකාය කුමක්ද?", "ඛුද්දක නිකාය", "දීඝ නිකාය", "මජ්ඣිම නිකාය", "සංයුත්ත නිකාය", "ධම්මපදය, ජාතකය, සුත්ත නිපාතය ආදී ග්‍රන්ථ 15 ක් ඛුද්දක නිකායට අයත් වේ."),
    q("ඛුද්දක නිකායේ පළමුවෙන්ම දැක්වෙන කුඩා පාඨ සංග්‍රහය කුමක්ද?", "ඛුද්දකපාඨය", "ධම්මපදය", "උදානය", "ඉතිවුත්තකය", "සරණාගමනය, දසසිල්, රතන, මංගල, මෙත්ත සූත්‍ර ඛුද්දකපාඨයේ එයි."),
    q("බුදුරදුන් සොම්නසින් පළ කළ ප්‍රීති වාක්‍ය 80 ක් අඩංගු ඛුද්දක නිකාය ග්‍රන්ථය කුමක්ද?", "උදාන පාලිය", "විමානවත්ථු", "පේතවත්ථු", "අපදානය", "බෝධි වග්ග, මුචලින්ද වග්ග ආදී වග්ග අටකින් උදාන පාලිය යුක්තය."),
    q("'භාග්‍යවතුන් වහන්සේ විසින් මෙසේ වදාරන ලදී' යනුවෙන් ආරම්භ වී ඛුජ්ජුත්තරාව හරහා ප්‍රචලිත වූ ග්‍රන්ථය කුමක්ද?", "ඉතිවුත්තකය", "සුත්ත නිපාතය", "චරියාපිටකය", "බුද්ධවංසය", "සූත්‍ර 112 කින් සමන්විත ඉතිවුත්තකය කෝසම්බියේදී ඛුජ්ජුත්තරාව අසා උගත්තාය."),
    q("පින් කළ අය දෙව්ලොව උපන් කතා හා පව් කළ අය ප්‍රේත ලොව උපන් කතා අඩංගු ග්‍රන්ථ යුගලය කුමක්ද?", "විමානවත්ථු හා පේතවත්ථු", "ථේරගාථා හා ථේරීගාථා", "නිද්දේස හා පටිසම්භිදාමග්ග", "ජාතක හා බුද්ධවංස", "කර්ම විපාකයේ ස්වභාවය ජනතාවට වටහා දීමට මෙම ග්‍රන්ථ දෙක උපකාරී වේ."),
    q("ගෞතම බුදුරදුන් ඇතුළු පෙර බුදුවරු විසිපස් නමකගේ චරිතාපදාන දැක්වෙන ග්‍රන්ථය කුමක්ද?", "බුද්ධවංසය", "අපදානය", "චරියාපිටකය", "නිද්දේසය", "දීපංකර බුදුන් සිට ගෞතම බුදුන් දක්වා විස්තර බුද්ධවංසයේ ඇතුළත්ය."),
    q("බෝසතාණන් වහන්සේ සසරේදී පාරමිතා පිරූ ආකාරය කතා 35 කින් දැක්වෙන ග්‍රන්ථය කුමක්ද?", "චරියාපිටකය", "විමානවත්ථු", "උදානය", "ධම්මපදය", "සැරියුත් හිමියන්ගේ ආරාධනයෙන් බුදුරදුන් දෙසූ බව සඳහන් චරියාපිටකය ඛුද්දක නිකායට අයත්ය."),
    q("සැරියුත් මහරහතන් වහන්සේ විසින් දේශනා කරන ලදැයි සැලකෙන ඛුද්දක නිකායේ ගැඹුරු ධර්ම විග්‍රහ ග්‍රන්ථ දෙක කුමක්ද?", "මහානිද්දේස හා චුල්ලනිද්දේස (සහ පටිසම්භිදාමග්ගය)", "ධම්මපද හා උදාන", "විමානවත්ථු හා පේතවත්ථු", "ජාතක හා අපදාන", "සුත්ත නිපාතයේ ගාථා විවරණය කරන නිද්දේස ග්‍රන්ථ සැරියුත් හිමි දෙසූහ."),
    q("බුද්ධ දේශනාවේ පරමාර්ථ ධර්ම හෙවත් ගැඹුරු මනෝවිද්‍යාත්මක හා දාර්ශනික විග්‍රහ ඇතුළත් පිටකය කුමක්ද?", "අභිධර්ම පිටකය", "විනය පිටකය", "සූත්‍ර පිටකය", "වංශ පිටකය", "සත්ව පුද්ගල භාවයෙන් තොර චිත්ත, චෛතසික, රූප, නිබ්බාන විග්‍රහ අභිධර්මයේ එයි."),
    q("අභිධර්ම පිටකය සමන්විත වන මූලික ප්‍රකරණ ග්‍රන්ථ ගණන කීයද?", "සතකි (සප්ත ප්‍රකරණ)", "පහකි", "දසයකි", "තුනකි", "ධම්මසංගණී, විභංග, ධාතුකථා, පුග්ගලපඤ්ඤත්ති, කථාවත්ථු, යමක, පට්ඨාන සප්ත ප්‍රකරණ වේ."),
    q("අභිධර්ම පිටකයේ පළමු ග්‍රන්ථය වන සිත් හා චෛතසික වර්ග කරන ග්‍රන්ථය කුමක්ද?", "ධම්මසංගණීප්පකරණය", "විභංගප්පකරණය", "ධාතුකථාප්පකරණය", "පට්ඨානප්පකරණය", "කුසල, අකුසල, අව්‍යාකෘත ධර්මයන් වර්ග කර ධම්මසංගණියේ විස්තර කෙරේ."),
    q("අභිධර්ම පිටකයේ පස්වන ග්‍රන්ථය වූ 'කථාවත්ථුප්පකරණය' රචනා කරන ලද්දේ කවුරුන් විසින්ද?", "මොග්ගලීපුත්ත තිස්ස මහරහතන් වහන්සේ", "මහා කාශ්‍යප හිමි", "ආනන්ද හිමි", "සැරියුත් හිමි", "තෙවන ධර්ම සංගායනාවේදී මිථ්‍යා මත ඛණ්ඩනය කරමින් මෙම ග්‍රන්ථය දේශනා කෙරිණි."),
    q("අභිධර්ම පිටකයේ හේතුඵල සම්බන්ධතා 24 ක් (සූවිසි ප්‍රත්‍යය) විස්තර කරන අවසාන ග්‍රන්ථය කුමක්ද?", "පට්ඨානප්පකරණය (මහාපකරණය)", "ධම්මසංගණිය", "පුග්ගලපඤ්ඤත්තිය", "යමකප්පකරණය", "හේතු ප්‍රත්‍යයේ සිට අවිගත ප්‍රත්‍යය දක්වා සූවිසි ප්‍රත්‍යය පට්ඨානයේ විස්තර වේ."),
    q("අභිධර්මය මිනිස් ලොව ප්‍රචලිත කිරීමට බුදුරදුන් වස් කාලයේ තව්තිසාවේ සිට විල් තෙරදී කෙටියෙන් දෙසුවේ කා හටද?", "සැරියුත් මහරහතන් වහන්සේට", "මුගලන් හිමිට", "ආනන්ද හිමිට", "රාහුල හිමිට", "අනෝතත්ත විල අසලදී බුදුරදුන්ගෙන් නය අසා සැරියුත් හිමි සිය ශිෂ්‍ය පන්සියයට උගැන්වූහ."),
    q("සම්පූර්ණ ධර්මස්කන්ධයන් ගණන ලෙස ත්‍රිපිටකයේ සඳහන් වන සංඛ්‍යාව කොපමණද?", "අසූහාර දහසකි (84,000)", "දස දහසකි", "සැට දහසකි", "ලක්ෂයකි", "විනය හා සූත්‍ර 42,000 බැගින් හෝ විනය 21,000, සූත්‍ර 21,000, අභිධර්ම 42,000 ලෙස 84,000 කි."),
    q("ප්‍රථම ධර්ම සංගායනාව පැවැත්වීමට ආසන්නතම හේතුව වූයේ කුමක්ද?", "බුදු පිරිනිවනින් සත් දිනකට පසු සුභද්‍ර නම් මහලු භික්ෂුව කළ අකැප ප්‍රකාශය", "රජවරුන් අතර යුද්ධය", "ධාතු බෙදා ගැනීම", "දුර්භික්ෂයක් ඇති වීම", "සුභද්‍රගේ අභද්‍ර වචන ඇසූ මහා කාශ්‍යප හිමි ධර්ම විනය රැකීමට සංගායනාවක් ඇරඹූහ."),
    q("ප්‍රථම ධර්ම සංගායනාව පවත්වන ලද ස්ථානය කුමක්ද?", "රජගහ නුවර වේභාර පර්වතයේ සප්තපර්ණී ගුහා ද්වාරය", "විශාලා නුවර වාලුකාරාමය", "පැළලුප් නුවර අශෝකාරාමය", "මාතලේ අලුවිහාරය", "බුද්ධ පරිනිර්වාණයෙන් තුන් මසකට පසු රජගහ නුවරදී මෙය පැවැත්විණි."),
    q("ප්‍රථම ධර්ම සංගායනාව සඳහා රාජ්‍ය අනුග්‍රහය ලබා දුන් මගධ අධිරාජයා කවුද?", "අජාසත් රජතුමා", "බිම්බිසාර රජතුමා", "කාලාශෝක රජතුමා", "ධර්මාශෝක රජතුමා", "අජාසත් රජු සප්තපර්ණී ගුහා ද්වාරයේ අලංකාර මණ්ඩපයක් කරවා සියලු පහසුකම් සැපයීය."),
    q("ප්‍රථම ධර්ම සංගායනාවේ මූලාසනය හෙබවූ මහතෙරුන් වහන්සේ කවුද?", "මහා කාශ්‍යප මහරහතන් වහන්සේ", "ආනන්ද හිමි", "උපාලි හිමි", "අනුරුද්ධ හිමි", "සංඝ ස්ථවිරව සිටි මහා කාශ්‍යප හිමි ප්‍රශ්න විමසමින් මූලාසනය දැරූහ."),
    q("ප්‍රථම ධර්ම සංගායනාවට සහභාගී වූ මහරහතන් වහන්සේලා සංඛ්‍යාව කීයද?", "පන්සිය නමකි", "හත්සිය නමකි", "දහස් නමකි", "අසූ නමකි", "ත්‍රිවිද්‍යා හා සිව්පිළිසිඹියාපත් රහතන් වහන්සේලා 500 ක් නිසා පංචසතික සංගීතිය නම් වේ."),
    q("ප්‍රථම සංගායනාවේදී විනය පිටකය විසඳීම සඳහා පත් කළ මහරහතන් වහන්සේ කවුද?", "උපාලි මහරහතන් වහන්සේ", "ආනන්ද මහරහතන් වහන්සේ", "මහා කාශ්‍යප හිමි", "පුණ්ණ හිමි", "විනයධර අග්‍ර උපාලි හිමි විනය පිටකය පිළිබඳ ප්‍රශ්නවලට පිළිතුරු දුන්හ."),
    q("ප්‍රථම සංගායනාවේදී සූත්‍ර පිටකය සංගායනා කළේ කවර තෙරුන් වහන්සේද?", "ආනන්ද මහරහතන් වහන්සේ", "උපාලි හිමි", "රේවත හිමි", "වක්කලී හිමි", "සංගායනාවට පෙර දින රාත්‍රියේ රහත් වූ ආනන්ද හිමි සූත්‍ර පිටකය විසඳූහ."),
    q("ප්‍රථම ධර්ම සංගායනාව පැවැත්වීම සඳහා ගත වූ කාලය කොපමණද?", "මාස හතකි", "මාස අටකි", "මාස නවයකි", "වසර දෙකකි", "නිකිණි පෝයෙන් ඇරඹී මාස හතක් පුරා රජගහ නුවරදී පැවැත්විණි."),
    q("ප්‍රථම සංගායනාවේදී ආනන්ද හිමියන් අතින් සිදු වූ අඩුපාඩු ලෙස චෝදනා කොට පිළිගත් කාරණා කීයක් තිබුණිද?", "පහකි (දුක්කට පහ)", "දෙකකි", "අටකි", "දහයකි", "කුදානුකුද්දක ශික්ෂා පද ගැන නොඇසීම, කාන්තා පැවිද්දට උත්සාහ කිරීම ආදී පහකි."),
    q("දෙවන ධර්ම සංගායනාව පැවැත්වීමට මූලික හේතුව වූයේ කුමන භික්ෂු පිරිසකගේ ක්‍රියා කලාපයද?", "වජ්ජිපුත්තක භික්ෂූන්ගේ දස අකැප වස්තුව", "දේවදත්ත භික්ෂූන්ගේ පංච වරය", "සුභද්‍රගේ ප්‍රකාශය", "මිථ්‍යාදෘෂ්ටික තීර්ථකයන්ගේ පැමිණීම", "සිංගිලෝන, ද්වංගුල, ගාමන්තර ආදී අකැප කරුණු 10 ක් වජ්ජිපුත්තකයෝ ඉදිරිපත් කළහ."),
    q("දෙවන ධර්ම සංගායනාව පවත්වන ලද්දේ බුද්ධ පරිනිර්වාණයෙන් වසර කීයකට පසුවද?", "වසර සියයකට පසුව", "වසර පනහකට පසුව", "වසර දෙසීයකට පසුව", "වසර තුන්සියයකට පසුව", "බු.ව. 100 දී විශාලා මහනුවරදී දෙවන සංගායනාව පැවැත්විණි."),
    q("දෙවන ධර්ම සංගායනාව පැවැත්වූ ස්ථානය හා විහාරය කුමක්ද?", "විශාලා මහනුවර වාලුකාරාමය", "රජගහ නුවර වේළුවනාරාමය", "පැළලුප් නුවර අශෝකාරාමය", "සැවැත් නුවර ජේතවනාරාමය", "සත්සියයක් රහතන් වහන්සේලා සහභාගී වූ බැවින් සත්තසතික සංගීතිය නම් වේ."),
    q("දෙවන ධර්ම සංගායනාවට රාජ්‍ය අනුග්‍රහය දැක්වූ රජු කවුද?", "කාලාශෝක රජතුමා", "අජාසත් රජතුමා", "ධර්මාශෝක රජතුමා", "විදුඩභ රජතුමා", "ශිශුනාග වංශික කාලාශෝක රජු මුලින් වැරදි මගක සිට පසුව සත්‍යය දැන රාජ්‍ය අනුග්‍රහය දුන්නේය."),
    q("වජ්ජිපුත්තක භික්ෂූන්ගේ දස අකැප වස්තු මුලින්ම දැක සංවේගයට පත්ව සංගායනාවට මුල් වූ තෙරුන් කවුද?", "යස කාකණ්ඩකපුත්ත හිමි", "රේවත හිමි", "සබ්බකාමී හිමි", "මහා කාශ්‍යප හිමි", "විශාලාවට වැඩි යස හිමියන් මුදල් පිළිගැනීම දැක එයට විරුද්ධ වූහ."),
    q("දෙවන ධර්ම සංගායනාවේ මූලාසනය දැරූ සංඝ ස්ථවිරයන් වහන්සේ කවුද?", "සබ්බකාමී මහරහතන් වහන්සේ (ප්‍රශ්න විමසීම රේවත හිමි)", "මොග්ගලීපුත්ත තිස්ස හිමි", "මහා කාශ්‍යප හිමි", "ආනන්ද හිමි", "බුදුන් දැක තිබූ වැඩිමහලු සබ්බකාමී හිමි විසඳුම් ලබා දුන් අතර රේවත හිමි ප්‍රධාන විය."),
    q("දෙවන ධර්ම සංගායනාව සඳහා ගත වූ කාලය කොපමණද?", "මාස අටකි", "මාස හතකි", "මාස නවයකි", "මාස තුනකි", "දස අකැප වස්තු ප්‍රතික්ෂේප කර ධර්ම විනය පිරිසිදු කිරීමට මාස 8 ක් ගත විය."),
    q("දෙවන සංගායනාවෙන් පරාජය වූ වජ්ජිපුත්තක භික්ෂූන් වෙනම රැස්වී ඇති කළ නිකාය කුමක්ද?", "මහාසාංඝික නිකාය", "ථේරවාද නිකාය", "මහාවිහාර නිකාය", "සර්වාස්තිවාද නිකාය", "මහාසංගීති පවත්වා මහාසාංඝික නමින් ශාසනයේ පළමු නිකාය භේදය ඇති විය."),
    q("තෙවන ධර්ම සංගායනාව පැවැත්වීමට ප්‍රධාන හේතුව කුමක්ද?", "ලාභ සත්කාර බලාපොරොත්තුවෙන් තීර්ථකයන් බුදු සසුනට ඇතුළු වී ශාසනය කිලිටි කිරීම", "දස අකැප වස්තු ඇතිවීම", "සුභද්‍රගේ කතාව", "චෝල ආක්‍රමණ", "අශෝක රජුගෙන් ලද දානමාන නිසා අන්‍ය තීර්ථකයෝ හොරෙන් සිවුරු පොරවා ගත්හ."),
    q("තෙවන ධර්ම සංගායනාව පැවැත්වූයේ කවර වර්ෂයක කවර ස්ථානයකද?", "බු.ව. 236 දී පැළලුප් නුවර අශෝකාරාමයේ", "බු.ව. 100 දී විශාලා මහනුවර", "බු.ව. 1 දී රජගහ නුවර", "බු.ව. 450 දී මාතලේ අලුවිහාරයේ", "ධර්මාශෝක රජුගේ අනුග්‍රහයෙන් පැළලුප් නුවර අශෝකාරාමයේ පැවැත්විණි."),
    q("තෙවන ධර්ම සංගායනාවට රාජ්‍ය අනුග්‍රහය හා ප්‍රධානත්වය දැරුවේ පිළිවෙළින් කවුද?", "ධර්මාශෝක රජතුමා හා මොග්ගලීපුත්ත තිස්ස මහරහතන් වහන්සේ", "කාලාශෝක රජතුමා හා සබ්බකාමී හිමි", "අජාසත් රජතුමා හා මහා කාශ්‍යප හිමි", "වළගම්බා රජතුමා හා මහා තිස්ස හිමි", "රජු ශාසන ශෝධනයට සහාය දුන් අතර මොග්ගලීපුත්ත තිස්ස හිමි ප්‍රධානත්වය දැරූහ."),
    q("තෙවන ධර්ම සංගායනාවට සහභාගී වූ මහරහතන් වහන්සේලා සංඛ්‍යාව කීයද?", "දහස් නමකි (1,000)", "පන්සිය නමකි", "හත්සිය නමකි", "දෙදහස් නමකි", "අශෝකාරාමයේදී රහතන් වහන්සේලා දහසක් එක්ව මාස නවයක් තුළ සංගායනා කළහ."),
    q("තෙවන ධර්ම සංගායනාවට පෙර ශාසනයෙන් පහ කරන ලද මිථ්‍යාදෘෂ්ටික හොර මහණුන් ගණන කොපමණද?", "හැට දහසකි (60,000)", "පන්සියයකි", "දහසකි", "සියයකි", "'කිංවාදී සම්මාසම්බුද්ධෝ' යන ප්‍රශ්නයෙන් විභජ්ජවාදී නොවූ සැම නෙරපූහ."),
    q("ධර්මාශෝක රජතුමා අන්‍ය තීර්ථකයන්ගෙන් බුදුරදුන්ගේ දහම හඳුනා ගැනීමට ඇසූ ප්‍රශ්නයට මොග්ගලීපුත්ත තිස්ස හිමි දුන් පිළිතුර කුමක්ද?", "බුදුරදුන් විභජ්ජවාදී වන සේක", "බුදුරදුන් ශාස්වතවාදීය", "බුදුරදුන් උච්ඡේදවාදීය", "බුදුරදුන් අකිරියවාදීය", "කරුණු බෙදා විමසා පැහැදිලි කරන බැවින් බුදුරදුන් විභජ්ජවාදී වන සේක."),
    q("තෙවන ධර්ම සංගායනාවේ අවසානයේ සිදු වූ අතිශය ශාසනික වැදගත්ම ප්‍රතිඵලය කුමක්ද?", "නව රටකට ධර්මදූත කණ්ඩායම් පිටත් කර හැරීම", "ත්‍රිපිටකය ලිවීම", "හෙළ අටුවා පරිවර්තනය", "මහාවිහාරය ඉදි කිරීම", "ශ්‍රී ලංකාව ඇතුළු රටවල් 9 කට ථේරවාද බුදුදහම ව්‍යාප්ත වීමයි."),
    q("තෙවන ධර්ම සංගායනාවෙන් පසු ශ්‍රී ලංකාවට (තම්බපණ්ණියට) වැඩම කළ ධර්මදූත ප්‍රධානියා කවුද?", "අනුබුදු මිහිඳු මහරහතන් වහන්සේ", "සෝණ හා උත්තර හිමිවරු", "මජ්ඣන්තික හිමි", "මහා රක්ඛිත හිමි", "මිහිඳු හිමි ප්‍රමුඛ ඉට්ඨිය, උත්තිය, සම්බල, භද්දසාල හා සුමන සාමණේර වැඩම කළහ."),
    q("තෙවන සංගායනාවෙන් පසු සුවණ්ණභූමියට (බුරුමය/තායිලන්තය) ධර්මදූත සේවයේ වැඩම කළ හිමිවරු කවුද?", "සෝණ හා උත්තර හිමිවරු", "මජ්ඣන්තික හිමි", "මහාදේව හිමි", "රක්ඛිත හිමි", "නවරට ධර්මදූත සේවාව යටතේ සුවණ්ණභූමියට වැඩම කළහ."),
    q("කාශ්මීර ගන්ධාර දේශයට ධර්මදූත සේවයේ වැඩම කළ මහරහතන් වහන්සේ කවුද?", "මජ්ඣන්තික මහරහතන් වහන්සේ", "මහා ධම්මරක්ඛිත හිමි", "යෝනක ධම්මරක්ඛිත හිමි", "මහා රක්ඛිත හිමි", "ආසීවිසෝපම සූත්‍රය දේශනා කර කාශ්මීර ගන්ධාරය පැහැදවූහ."),
    q("ශ්‍රී ලංකාවේදී ත්‍රිපිටකය ප්‍රථම වරට ග්‍රන්ථාරූඪ කිරීම (පුස්තකාරූඪ කිරීම) සිදු වූයේ කවර රජුගේ කාලයේදීද?", "වළගම්බා (වට්ටගාමිණී අභය) රජතුමා", "දේවානම්පියතිස්ස රජතුමා", "දුටුගැමුණු රජතුමා", "මහානාම රජතුමා", "බු.ව. 450 දී පමණ වළගම්බා රජ සමයේ මාතලේ අලුවිහාරයේදී සිදුවිය."),
    q("ත්‍රිපිටකය ග්‍රන්ථාරූඪ කිරීම සිදු කළ ස්ථානය හා ඊට අනුග්‍රහය දැක්වූ ප්‍රාදේශීය අධිපතියා කවුද?", "මාතලේ අලුවිහාරය හා ප්‍රාදේශීය රජ කෙනෙකු (රට්ඨිකයෙකු)", "මිහින්තලය හා කාවන්තිස්ස රජු", "අනුරාධපුර රුවන්වැලි සෑය", "පොළොන්නරුව හා පරාක්‍රමබාහු රජු", "රහතන් වහන්සේලා පන්සිය නමක් අලුවිහාරයේදී පුස්කොළපොත්වල ලියූහ."),
    q("ත්‍රිපිටකය ලිඛිත මාධ්‍යයට පත් කිරීමට ප්‍රධාන හේතුවක් වූයේ කුමක්ද?", "බැමිණිතියා සාය දුර්භික්ෂය, සතුරු ආක්‍රමණ හා භික්ෂූන්ගේ මතක ශක්තිය හීන වීම", "කඩදාසි සොයා ගැනීම", "වෙනත් ආගම් ඉගැන්වීමට", "රජ මැදුරේ තැන්පත් කිරීමට", "මුඛ පරම්පරාගතව රැකගෙන ආ දහම විනාශ වීමේ අවදානම නිසා ග්‍රන්ථාරූඪ කෙරිණි."),
    q("මාතලේ අලුවිහාරයේ පැවති සිව්වන (ශ්‍රී ලංකා) සංගායනාවේ ප්‍රධානත්වය දැරූ තෙරුන් කවුද?", "කුන්තගත්තතිස්ස හිමි ප්‍රමුඛ රහතන් වහන්සේලා", "මිහිඳු හිමි", "බුද්ධඝෝෂ හිමි", "මහානාම හිමි", "පාලි ත්‍රිපිටකය පමණක් නොව හෙළ අටුවා ද එහිදී ලේඛනගත කෙරිණි."),
    q("බුද්ධඝෝෂ හිමි මෙරටට වැඩම කර හෙළ අටුවා පාලියට පරිවර්තනය කළේ කවර රජුගේ සමයේදීද?", "මහානාම රජතුමාගේ", "වළගම්බා රජතුමාගේ", "ධාතුසේන රජතුමාගේ", "මහසෙන් රජතුමාගේ", "ක්‍රි.ව. 5 වන සියවසේ මහානාම රජ සමයේ මහාවිහාරයේදී හෙළ අටුවා පාලියට නැගූහ."),
    q("බුද්ධඝෝෂ හිමියන් අනුරාධපුර මහාවිහාරයේදී තම පාණ්ඩිත්‍යය පෙන්වීම සඳහා රචනා කළ මුල්ම කෘතිය කුමක්ද?", "විසුද්ධිමග්ගය", "සමන්තපාසාදිකාව", "සුමංගලවිලාසිනිය", "අත්ථසාලිනිය", "'සීලේ පතිට්ඨාය නරෝ සපඤ්ඤෝ' ගාථාව විස්තර කරමින් විසුද්ධිමග්ගය රචනා කළහ."),
    q("විනය පිටකය සඳහා බුද්ධඝෝෂ හිමියන් විසින් රචනා කරන ලද අටුවාව කුමක්ද?", "සමන්තපාසාදිකාව", "සුමංගලවිලාසිනිය", "පපංචසූදනිය", "සාරත්ථප්පකාසිනිය", "මහා අට්ඨකථා ආශ්‍රයෙන් විනය පිටකයට සමන්තපාසාදිකාව ලියූහ."),
    q("දීඝ නිකාය සඳහා රචනා කර ඇති පාලි අටුවාව කුමක්ද?", "සුමංගලවිලාසිනිය", "පපංචසූදනිය", "මනෝරථපූරණිය", "සාරත්ථප්පකාසිනිය", "සුමංගලවිලාසිනිය දීඝ නිකායේ අටුවාවයි."),
    q("මජ්ඣිම නිකායට ලියැවුණු පාලි අටුවාව හඳුන්වන්නේ කුමන නමින්ද?", "පපංචසූදනිය", "සුමංගලවිලාසිනිය", "මනෝරථපූරණිය", "පරමත්ථජෝතිකාව", "මජ්ඣිම නිකායේ සූත්‍රවල අර්ථ විවරණය පපංචසූදනියයි."),
    q("සංයුත්ත නිකායේ පාලි අටුවාව හඳුන්වන නාමය කුමක්ද?", "සාරත්ථප්පකාසිනිය", "මනෝරථපූරණිය", "අත්ථසාලිනිය", "කංඛාවිතරණිය", "බුද්ධඝෝෂ හිමි සංයුත්ත නිකායට මෙම අටුවාව ලියූහ."),
    q("අංගුත්තර නිකාය සඳහා රචිත පාලි අටුවාව කුමක්ද?", "මනෝරථපූරණිය", "සාරත්ථප්පකාසිනිය", "සම්මෝහවිනෝදනිය", "ධම්මපදට්ඨකථාව", "අංගුත්තර නිකායේ සූත්‍ර විස්තර කෙරෙන අටුවාව මනෝරථපූරණියයි."),
    q("පටිසම්භිදාමග්ගය සඳහා අටුවාවක් ලෙස 'සද්ධම්මප්පකාසිනිය' රචනා කළේ කවුද?", "මහානාම හිමි", "බුද්ධඝෝෂ හිමි", "ධම්මපාල හිමි", "බුද්ධදත්ත හිමි", "බුද්ධඝෝෂ හිමියන්ගෙන් පසුව වැඩි අටුවාචාරීහු ඛුද්දක නිකායේ ඉතිරි ග්‍රන්ථවලට අටුවා ලියූහ."),
    q("උදාන, ඉතිවුත්තක, විමානවත්ථු, පේතවත්ථු ආදියට 'පරමත්ථදීපනී' අටුවාව ලියූ අටුවාචාරී හිමි කවුද?", "ධම්මපාල හිමි", "මහානාම හිමි", "උපසේන හිමි", "බුද්ධදත්ත හිමි", "බදරතිත්ථ විහාරවාසී ධම්මපාල හිමි ප්‍රමුඛ අටුවාචාරියෙකි."),
    q("මහාවිහාරයට විරුද්ධව මහායාන හා වෛතුල්‍යවාදී අදහස් මෙරට ප්‍රචලිත වූ විහාරය කුමක්ද?", "අභයගිරි විහාරය", "මිහින්තලේ විහාරය", "ථූපාරාම විහාරය", "තන්තිරිමලේ විහාරය", "වළගම්බා රජුගේ සමයේ ඉදි වූ අභයගිරිය පසුව විවිධ නිකායන්ට විවෘත විය."),
    q("පොළොන්නරු සමයේදී අටුවාවල ඇති ගැඹුරු තැන් තවදුරටත් පැහැදිලි කිරීමට ලියූ ග්‍රන්ථ හඳුන්වන්නේ කෙසේද?", "ටීකා ග්‍රන්ථ", "වංශකතා", "පිරිවෙන් පොත්", "සන්දේශ කාව්‍ය", "සාරිපුත්ත හිමි ආදී පඬිවරු ටීකා හා ගැටපද රචනා කළහ."),
    q("සංස්කෘත හා පාලි භාෂාවෙන් ලියැවුණු ත්‍රිපිටකයේ ප්‍රධාන සිංහල පරිවර්තනය ලෙස රාජ්‍ය අනුග්‍රහයෙන් බිහි වූයේ කුමක්ද?", "බුද්ධ ජයන්ති ත්‍රිපිටක ග්‍රන්ථමාලාව", "සිංහල වංශකතාව", "සද්ධර්මරත්නාවලිය", "පූජාවලිය", "2500 බුද්ධ ජයන්තිය නිමිත්තෙන් මුළු ත්‍රිපිටකයම සිංහලට පරිවර්තනය කෙරිණි."),
    q("බුරුමයේදී (මියන්මාරයේ) පවත්වන ලද පස්වන හා හයවන ධර්ම සංගායනාවන් අතරින් හයවන සංගායනාව (ඡට්ඨ සංගායනාව) පැවැත්වූයේ කවදාද?", "1954-1956 (2500 බුද්ධ ජයන්ති සමයේ)", "1871 දී", "1900 දී", "2000 දී", "රැන්ගුන් නුවරදී ශ්‍රී ලංකාව ඇතුළු ථේරවාද රටවල් එක්ව ඡට්ඨ සංගායනාව පැවැත්වූහ."),
    q("ත්‍රිපිටකයේ සඳහන් ධර්ම කොටස් වර්ග කරන 'නවාංග ශාස්තෘ ශාසනයට' අයත් නොවන්නේ කුමක්ද?", "නාට්‍ය", "සුත්ත", "ගෙය්‍ය", "ගාථා", "සුත්ත, ගෙය්‍ය, වෙය්‍යාකරණ, ගාථා, උදාන, ඉතිවුත්තක, ජාතක, අබ්භූතධම්ම, වේදල්ල නවාංගයයි."),
    q("නවාංග ශාස්තෘ ශාසනයේ ගද්‍ය හා පද්‍ය මිශ්‍රව ඇති දේශනා හඳුන්වන්නේ කුමන අංගයෙන්ද?", "ගෙය්‍ය", "සුත්ත", "ගාථා", "උදාන", "සගාථ වග්ගය වැනි ගද්‍ය පද්‍ය මිශ්‍ර සූත්‍ර ගෙය්‍ය අංගයට අයත් වේ."),
    q("ධර්මය කටපාඩමින් හා පොත්පත්වලින් සුරක්ෂිත කිරීම සඳහා පුරාණයේ භික්ෂූන් වහන්සේලා බෙදා වෙන් කරගත් පරම්පරා ක්‍රමය කුමක්ද?", "භාණක පරම්පරාව", "රාජ පරම්පරාව", "සිටු පරම්පරාව", "වෙළඳ පරම්පරාව", "දීඝභාණක, මජ්ඣිමභාණක, සංයුත්තභාණක, අංගුත්තරභාණක ලෙස නිකායන් රැකගත්හ."),
    q("විනය පිටකයේ සඳහන් සාමණේරවරුන් විසින් පිළිපැදිය යුතු ශික්ෂාපද ගණන කීයද?", "දසයකි (දස ශීලය)", "පහකි", "අටකි", "විසිපහකි", "ප්‍රාණඝාතයේ සිට ජාතරූපරජත පටිග්ගහණය දක්වා සාමණේර දස ශික්ෂාපද ඇත."),
    q("ප්‍රථම ධර්ම සංගායනාවේදී ආනන්ද හිමි චෝදනාවකට ලක් වූ නමුත් පසුකාලීන සංඝ සමාජයට ඉතා වැදගත් වූ කාරණය කුමක්ද?", "කුදානුකුද්දක ශික්ෂා පද ඉවත් නොකර සියල්ල රැක ගැනීම", "පාරාජිකා ඉවත් කිරීම", "භික්ෂුණී ශාසනය නැවැත්වීම", "පිඬුසිඟා යෑම නැවැත්වීම", "කුදානුකුද්දක යනු කුමක්දැයි එකඟතාවක් නොවූ බැවින් කිසිදු ශික්ෂා පදයක් ඉවත් නොකෙරිණි."),
    q("බුද්ධ වචනය ගැඹුරින් අර්ථ නිරූපණය කිරීමට හෙළ අටුවා ඇසුරින් සමන්තපාසාදිකාව ලියූ විට ඊට අමතරව විනය කර්ම ගැන රචිත කෘතිය කුමක්ද?", "කංඛාවිතරණිය (පාතිමෝක්ෂ අටුවාව)", "විසුද්ධිමග්ගය", "මහාවංසය", "දීපවංසය", "පාතිමෝක්ෂය විවරණය කරමින් බුද්ධඝෝෂ හිමි කංඛාවිතරණිය ලියූහ."),
    q("අභිධර්ම පිටකයේ සාරාංශය ඉගෙනීමට ප්‍රකට අත්පොතක් වන 'අභිධම්මත්ථ සංගහය' රචනා කළේ කවුද?", "අනුරුද්ධ හිමියන්", "බුද්ධඝෝෂ හිමියන්", "නාගසේන හිමියන්", "සැරියුත් හිමියන්", "පොළොන්නරු යුගයේ අනුරුද්ධ හිමි රචනා කළ මෙය චිත්ත, චෛතසික ආදිය හඳුන්වා දෙයි."),
    q("ශ්‍රී ලංකාවට අමතරව 'ථේරවාද බුදුදහම' ප්‍රධාන වශයෙන් පවතින ආසියානු රටවල් මොනවාද?", "මියන්මාරය, තායිලන්තය, කාම්බෝජය හා ලාඕසය", "ජපානය, චීනය හා කොරියාව", "ටිබෙටය හා මොංගෝලියාව", "වියට්නාමය හා තායිවානය", "තෙවන සංගායනාවෙන් පසු දකුණු හා ගිනිකොනදිග ආසියාවේ ථේරවාදය ස්ථාපිත විය."),
    q("චීනය, ජපානය හා කොරියාව වැනි නැගෙනහිර ආසියාතික රටවල ප්‍රචලිත වූ බුදුදහමේ ප්‍රධාන සම්ප්‍රදාය කුමක්ද?", "මහායාන සම්ප්‍රදාය", "ථේරවාද සම්ප්‍රදාය", "සෞත්‍රාන්තික සම්ප්‍රදාය", "වෛභාෂික සම්ප්‍රදාය", "බෝධිසත්ව සංකල්පය ප්‍රමුඛ කොටගත් මහායානය උතුරු හා නැගෙනහිර ආසියාවේ පැතිරිණි."),
    q("පාලි ත්‍රිපිටකයේ සඳහන් 'බ්‍රහ්මදණ්ඩය' හා 'උක්ඛේපනීය කර්මය' වැනි විනය දඬුවම් පනවා ඇත්තේ කුමක් සඳහාද?", "සංඝ සමාජයේ විනය, සමගිය හා පවිත්‍රතාව ආරක්ෂා කිරීමට", "භික්ෂූන්ගෙන් මුදල් අය කිරීමට", "විහාර කඩා දැමීමට", "රජුට දඬුවම් කිරීමට", "වැරදි කළ භික්ෂුවකට තම වරද වටහාගෙන නිවැරදි වීමට අවස්ථාව දීම සඳහාය."),
    q("ධර්ම සංගායනා ඉතිහාසයේ 'ප්‍රථම ධර්ම සංගායනාවට' සම්බන්ධ නොවූ මහරහතන් වහන්සේ කවුද?", "සැරියුත් මහරහතන් වහන්සේ (බුදුන්ට පෙර පිරිනිවන් පෑ බැවින්)", "මහා කාශ්‍යප හිමි", "ආනන්ද හිමි", "උපාලි හිමි", "සැරියුත් හා මුගලන් අග්‍රශ්‍රාවක දෙනම බුදු පිරිනිවනට පෙරාතුව පිරිනිවන් පෑ සේක."),
    q("සූත්‍ර පිටකයේ ඛුද්දක නිකායට අයත් 'නිද්දේස' ග්‍රන්ථය මගින් විවරණය කෙරෙන්නේ කවර සූත්‍ර සංග්‍රහයක්ද?", "සුත්ත නිපාතයේ අට්ඨක හා පාරායන වග්ග", "ධම්මපද ගාථා", "බ්‍රහ්මජාල සූත්‍රය", "සතිපට්ඨාන සූත්‍රය", "මහානිද්දේසයෙන් අට්ඨක වග්ගයද, චුල්ලනිද්දේසයෙන් පාරායන වග්ගය හා ඛග්ගවිසාණ සූත්‍රයද විස්තර වේ."),
    q("ත්‍රිපිටකය ජාතික උරුමයක් බවට ප්‍රකාශයට පත් කිරීමෙන් ශ්‍රී ලංකාව අපේක්ෂා කළ ප්‍රධාන පරමාර්ථය කුමක්ද?", "නිර්මල ථේරවාද ත්‍රිපිටකයේ පිරිසිදු පාඨය විකෘති නොවී අනාගතයට සුරැකීම", "පොත් විකිණීම", "භාෂාව වෙනස් කිරීම", "රාජ්‍ය ලාංඡනය වෙනස් කිරීම", "ලෝක උරුමයක් ලෙස නිර්මල බුද්ධ වචනය ආරක්ෂා කිරීම මෙහි අරමුණ විය."),
    q("විනය පිටකයේ පළමු පාරාජිකා ශික්ෂාපදය පැනවීමට මුල් වූ භික්ෂුව කවුද?", "සුදින්න භික්ෂුව", "දේවදත්ත භික්ෂුව", "ඡන්න භික්ෂුව", "උදායි භික්ෂුව", "වසර විස්සක් පමණ යනතුරු ශික්ෂා පද පැනවීමට අවශ්‍ය නොවූ අතර සුදින්නගේ වරදින් පළමු පාරාජිකාව පැණවිණි."),
    q("බුදුරදුන් ප්‍රථමයෙන්ම විනය නීති පැනවීම ආරම්භ කළේ බුද්ධත්වයෙන් වසර කීයකට පසුවද?", "වසර විස්සකට පසුව", "වසර පහකට පසුව", "වසර හතළිහකට පසුව", "පළමු වසරේදීම", "මුල් විසි වසර තුළ භික්ෂූන් ස්වයං විනයෙන් යුක්ත වූ නිසා නීති පැනවීම අවශ්‍ය නොවීය."),
    q("සංඝ සමාජයේ විනය නීති පැනවීමේ ප්‍රධාන පරමාර්ථ දහයක් බුදුරදුන් දේශනා කළේය. ඊට අයත් පළමු කරුණ කුමක්ද?", "සංඝසුට්ඨුතාය (සංඝයාගේ යහපැවැත්ම පිණිස)", "ධනය ඉපයීම පිණිස", "රාජ්‍ය බලය පිණිස", "ගැටුම් වැඩි කිරීම පිණිස", "සංඝසුට්ඨුතාය, සංඝඵාසුතාය ආදී අර්ථවසයන් දහයක් උදෙසා ශික්ෂාපද පැණවිණි."),
    q("භික්ෂූන් වහන්සේලා විසින් සතියකට දෙවරක් හෝ පොහොය දිනවල සිදු කරන 'උපෝසථ කර්මය' යනු කුමක්ද?", "රැස්වී පාතිමෝක්ෂය උදෙසා පිරිසිදු ශීලය සිහිපත් කිරීම", "ආහාර පූජා කිරීම", "ගොඩනැගිලි තැනීම", "පෙරහැර පැවැත්වීම", "සංඝ සමගිය හා විනය පවිත්‍රතාව රැකගැනීම උපෝසථ කර්මයේ අරමුණයි."),
    q("දෙවන ධර්ම සංගායනාවේදී වජ්ජිපුත්තකයන්ගේ දස අකැප වස්තු අතර තිබූ 'ජාතරූපරජත' යනු කුමක්ද?", "රන් රිදී හා මිල මුදල් පිළිගැනීම", "මධ්‍යාහ්නයෙන් පසු ආහාර ගැනීම", "අඟුළු දෙකක් ඉක්මවා ආහාර ගැනීම", "මස් මාංශ අනුභවය", "භික්ෂූන් වහන්සේලා මිල මුදල් පරිහරණය කිරීම විනය විරෝධී බව සංගායනාවේදී තහවුරු කෙරිණි."),
    q("ප්‍රථම සංගායනාවේ සිට මාතලේ අලුවිහාර සංගායනාව දක්වා ධර්මය රැකගෙන ආ ක්‍රමය හඳුන්වන්නේ කෙසේද?", "මුඛ පරම්පරාගත ක්‍රමය (ශ්‍රැති පරම්පරාව)", "මුද්‍රණ ක්‍රමය", "ලෝහ තහඩු ක්‍රමය", "ප්‍රතිමා ක්‍රමය", "ගුරු කුලවල භාණක හිමිවරු කටපාඩමින් ත්‍රිපිටකය සුරැකූහ."),
    q("බුද්ධ පරිනිර්වාණයෙන් පසු මහායාන නිකායන්හි බිහි වූ ප්‍රධාන සංස්කෘත ග්‍රන්ථයක් වන්නේ කුමක්ද?", "සද්ධර්මපුණ්ඩරීක සූත්‍රය", "ධම්මසංගණීප්පකරණය", "සමන්තපාසාදිකාව", "පරිවාර පාලිය", "ප්‍රඥාපාරමිතා හා සද්ධර්මපුණ්ඩරීක සූත්‍රය මහායාන ප්‍රධාන ග්‍රන්ථ වේ."),
    q("අභිධර්ම පිටකයේ හතරවන ග්‍රන්ථය වන 'පුග්ගලපඤ්ඤත්තියෙහි' ප්‍රධාන වශයෙන් විස්තර කෙරෙන්නේ කුමක්ද?", "පුද්ගල චරිත ස්වභාවයන් හා වර්ගීකරණයන්", "ධාතු කොටස්", "සූවිසි ප්‍රත්‍යය", "විනය නීති", "සමාජයේ විවිධ පුද්ගලයන්ගේ මානසික හා ගුණාත්මක තත්ත්වයන් විස්තර කෙරේ."),
    q("අභිධර්ම පිටකයේ දෙවන ග්‍රන්ථය වන 'විභංගප්පකරණයේ' ඇතුළත් විභංග ගණන කීයද?", "දහඅටකි (18)", "පහකි", "සතකි", "විසිහතරකි", "ඛන්ධ, ආයතන, ධාතු, සච්ච ආදී විභංග 18 කින් යුක්තය."),
    q("විනය පිටකයේ 'සේඛියා ධර්ම' මගින් භික්ෂූන්ට උගන්වන්නේ කුමක්ද?", "සිවුරු හැඳීම, පිණ්ඩපාතයේ වැඩීම, දහම් දෙසීම ආදී එදිනෙදා ආචාර විධි", "රාජ්‍ය පාලන නීති", "අභිධර්ම විග්‍රහ", "භාවනා සමාපත්ති", "75 ක් වූ සේඛියා ධර්ම පැවිද්දන්ගේ මනා සංවරය හා පෞරුෂය පෙන්වයි."),
    q("තෙවන ධර්ම සංගායනාවෙන් පසු මිහිඳු හිමියන් හෙළ බසට නගා මෙරට පැවැත්වූ අටුවා සම්ප්‍රදාය කුමක්ද?", "හෙළ අටුවා (මහා අට්ඨකථා ආදිය)", "ටීකා සම්ප්‍රදාය", "සංස්කෘත අටුවා", "දෙමළ අටුවා", "මහා අට්ඨකථා, මහා පච්චරිය, කුරුන්දි අට්ඨකථා ලෙස හෙළ අටුවා පැවතුණි.")
  )
}
